UNKNOWN={None,'','故事时代未知','待核','待分类','未知'}
def is_known(p):
    v=p['value']
    return p['present'] and not (v is None or isinstance(v,str) and v in UNKNOWN)
def main(part):
    start=(part-1)*50;end=min(part*50,300)
    assert all(i in D for i in range(start,end)),'Only manually supplied descriptors allowed'
    records=[];counts=dict.fromkeys(FIELDS,0);missing_count=preserved_count=0
    for i in range(start,end):
        s=selection['records'][i];values=D[i];fields={};missing={};preserved={};unproposed={}
        for fi,k in enumerate(FIELDS):
            pre=s['pre_dimension_fields'][k];known=any(is_known(p) for p in pre.values())
            val=values[fi] if fi<len(values) else None
            if known:
                why='准确基线已有非占位值，原值及原键presence保留，不覆盖。'
                preserved[k]={'reason':why,'pre_presence':copy.deepcopy(pre)}
                unproposed[k]={'status':'existing_known_preserved','reason':why,'pre_presence':copy.deepcopy(pre)}
                preserved_count+=1;continue
            if not val:
                why='本批准确核心与原范围不足以安全提炼；不由题名、出版年、体裁或其他卷猜测。'
                missing[k]=why;unproposed[k]={'status':'actual_missing','reason':why,'pre_presence':copy.deepcopy(pre)}
                missing_count+=1;continue
            role='interpretive_description_derived_from_exact_existing_core' if k in ['narrative_mechanism','reality_relation'] else 'explicit_setting_or_scoped_expression_in_existing_analysis_pending_review'
            fields[k]={'proposed_value':val,'basis':{'issue':copy.deepcopy(s['current_core_fields']['issue']),'facet_bases':[f['basis'] for f in s['current_core_fields']['issue_facets'] or []]},'role':role,'known_or_derived':'准确原分析的文学解释，待独立核对' if k in ['narrative_mechanism','reality_relation'] else '原分析／范围明确的设定或表达，待独立核对','support_scope':'只限准确原A、活跃核心和原完整历史声明的简介、节选、选篇或已有知识；本轮没有重读旧URL或新材料。叙事不证明全文章序，科学设定不评可行性，现实类比不评分预测。','source_analysis_ref':copy.deepcopy(s['source_analysis_ref']),'active_core_assertion_sha256':s['active_core_assertion_sha256'],'original_material_scope':copy.deepcopy(s['original_material_scope']),'retained_sources':copy.deepcopy(s['retained_source_urls']),'new_material_read':False,'independently_verified':False}
            counts[k]+=1
        assert set(fields)|set(unproposed)==set(FIELDS) and not set(fields)&set(unproposed)
        records.append({'id':s['id'],'identity':copy.deepcopy(s['identity']),'selection_index':i,'selection_reference':{'file':'work/evidence/global-breadth-selection-round4.json','file_sha256':sha(SB),'pointer':f'$.records[{i}]','record_sha256':rs(s)},'source_sort_year':s['source_sort_year'],'current_grain_and_date':copy.deepcopy(s['current_grain_and_date']),'source_index_sha256':s['current_source_index_sha256'],'source_analysis_ref':copy.deepcopy(s['source_analysis_ref']),'active_core_assertion_sha256':s['active_core_assertion_sha256'],'whole_prior_reference':{'file':'work/evidence/global-breadth-selection-round4.json','file_sha256':sha(SB),'pointer':f'$.records[{i}].current_source_search_log','record_sha256':s['current_source_search_log_sha256']},'original_provenance_scope':{'record_presence':copy.deepcopy(s['original_record_provenance_presence']),'metadata_presence':copy.deepcopy(s['original_metadata_provenance_presence']),'original_metadata_reference':copy.deepcopy(s['source_analysis_metadata_reference']),'absence_policy':'原完整metadata和历史逐值保留；实际原缺失保持未知，不造0次数、owner、log或cache。'},'proposed_fields':fields,'unproposed_fields':unproposed,'missing_fields':missing,'preserved_known_fields':preserved,'verification_status':'knowledge_added_unverified','sources':copy.deepcopy(s['retained_source_urls']),'source_reference_note':'原URL仅保留其原scope，本轮0新查读，不提升材料或独立核验等级。'})
    metadata={'status':'frozen_private_dimension_proposal_checkpoint','date':'2026-10-06','delegate':'global_history','breadth_round':4,'target_round':94,'part':part,'selection_file':'work/evidence/global-breadth-selection-round4.json','selection_sha256':sha(SB),'canonical_snapshot_sha256':selection['metadata']['canonical_sha256'],'source_publication_pending':True,'last_published_separate':copy.deepcopy(selection['metadata']['last_published_separate']),'selection_indices':list(range(start,end)),'record_count':len(records),'proposed_field_count':sum(counts.values()),'field_counts':counts,'unproposed_field_slots':len(records)*5-sum(counts.values()),'actual_missing_field_slots':missing_count,'preserved_known_field_slots':preserved_count,'new_query_count':0,'new_open_count':0,'new_core_count':0,'new_material_read_count':0,'new_original_fulltext_read_count':0,'independently_verified_count':0,'scope':'Manual single-pass descriptors from exact existing core and declared original scope. Five optional fields only; genuine unknowns differ from existing known values left unproposed. Original identity/grain/source/date/core/duration/space/feasibility and provenance presence unchanged.'}
    assert sum(counts.values())+missing_count+preserved_count==len(records)*5
    out=P/f'global-breadth-round4-part{part}-proposals.json';assert not out.exists(),'Frozen checkpoint cannot be overwritten'
    raw=(json.dumps({'metadata':metadata,'records':records},ensure_ascii=False,indent=2)+'\n').encode();out.write_bytes(raw)
    print(json.dumps({'file':str(out),'sha256':sha(raw),'records':len(records),'fields':sum(counts.values()),'counts':counts,'unproposed':metadata['unproposed_field_slots'],'actual_missing':missing_count,'known_preserved':preserved_count},ensure_ascii=False))
if __name__=='__main__':main(int(sys.argv[1]))
